import{_ as t,o as a,c as d,a0 as o}from"./chunks/framework.DeoJcRVf.js";const E=JSON.parse('{"title":"Matriz y Configuración de AWS Lambdas","description":"","frontmatter":{},"headers":[],"relativePath":"lambdas.md","filePath":"lambdas.md"}'),l={name:"lambdas.md"};function s(n,e,c,i,r,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="matriz-y-configuracion-de-aws-lambdas" tabindex="-1">Matriz y Configuración de AWS Lambdas <a class="header-anchor" href="#matriz-y-configuracion-de-aws-lambdas" aria-label="Permalink to &quot;Matriz y Configuración de AWS Lambdas&quot;">​</a></h1><p>El backend de Flowex está compuesto por funciones serverless en <strong>Node.js 24</strong> dentro de las subredes privadas de la VPC compartida. Cada función se llama <code>flowex-&lt;servicio&gt;-&lt;env&gt;</code> (por ejemplo <code>flowex-auth-api-prod</code>). <code>Flowex-iac</code> la crea y fija su configuración, y el repositorio del servicio despliega su código. Ver <a href="/deployment">Despliegue</a>.</p><hr><h2 id="📊-matriz-master-de-lambdas" tabindex="-1">📊 Matriz Máster de Lambdas <a class="header-anchor" href="#📊-matriz-master-de-lambdas" aria-label="Permalink to &quot;📊 Matriz Máster de Lambdas&quot;">​</a></h2><p>Memoria y timeout según <code>Flowex-iac/lib/config/environments.ts</code> (iguales en dev y prod).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Función Lambda</th><th style="text-align:left;">Ámbito</th><th style="text-align:left;">Memoria</th><th style="text-align:left;">Timeout</th><th style="text-align:left;">Triggers</th><th style="text-align:left;">Secretos que lee (por nombre)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>Flowex-auth-api-lambda</code></strong></td><td style="text-align:left;">Público</td><td style="text-align:left;"><code>512 MB</code></td><td style="text-align:left;"><code>10 s</code></td><td style="text-align:left;">API Gateway REST (<code>/auth/*</code>)</td><td style="text-align:left;"><code>auth/jwt</code></td></tr><tr><td style="text-align:left;"><strong><code>Flowex-auth-admin-lambda</code></strong></td><td style="text-align:left;">Privado (VPC)</td><td style="text-align:left;"><code>256 MB</code></td><td style="text-align:left;"><code>10 s</code></td><td style="text-align:left;">API Gateway (<code>/internal/*</code>, pedidos, rutas), EventBridge cada 15 min (planificación)</td><td style="text-align:left;"><code>auth/jwt</code>, <code>orders/delivery-pin-key</code>, <code>google/maps</code>, <code>google/route-optimization</code></td></tr><tr><td style="text-align:left;"><strong><code>Flowex-registration-public-lambda</code></strong></td><td style="text-align:left;">Público</td><td style="text-align:left;"><code>512 MB</code></td><td style="text-align:left;"><code>10 s</code></td><td style="text-align:left;">API Gateway REST (<code>/registration/*</code>)</td><td style="text-align:left;"><code>auth/jwt</code></td></tr><tr><td style="text-align:left;"><strong><code>Flowex-registration-admin-lambda</code></strong></td><td style="text-align:left;">Admin / Event</td><td style="text-align:left;"><code>256 MB</code></td><td style="text-align:left;"><code>15 s</code></td><td style="text-align:left;">API Gateway Admin / Invocación IAM</td><td style="text-align:left;"><code>auth/jwt</code></td></tr><tr><td style="text-align:left;"><strong><code>Flowex-otp-service-lambda</code></strong></td><td style="text-align:left;">Público</td><td style="text-align:left;"><code>512 MB</code></td><td style="text-align:left;"><code>10 s</code></td><td style="text-align:left;">API Gateway REST (<code>/otp/*</code>, <code>/notifications/whatsapp</code>)</td><td style="text-align:left;"><code>auth/jwt</code>, <code>meta/whatsapp</code></td></tr><tr><td style="text-align:left;"><strong><code>Flowex-payments-api-lambda</code></strong></td><td style="text-align:left;">Público</td><td style="text-align:left;"><code>256 MB</code></td><td style="text-align:left;"><code>10 s</code></td><td style="text-align:left;">API Gateway REST (<code>/payments/*</code>, <code>/webhooks/*</code>)</td><td style="text-align:left;"><code>auth/jwt</code>, <code>mercadopago/checkout-pro</code>, <code>fintoc/payments</code></td></tr><tr><td style="text-align:left;"><strong><code>Flowex-notification-lambda</code></strong></td><td style="text-align:left;">SQS / Directo</td><td style="text-align:left;"><code>256 MB</code></td><td style="text-align:left;"><code>10 s</code></td><td style="text-align:left;">Cola <code>flowex-notifications-queue-&lt;env&gt;</code> y API Gateway (<code>/notifications/*</code>)</td><td style="text-align:left;"><code>auth/jwt</code>, <code>meta/whatsapp</code> (sin permiso IAM, ver <a href="/deployment#_9-brechas-conocidas">brechas</a>)</td></tr><tr><td style="text-align:left;"><strong><code>Flowex-consent-worker-lambda</code></strong></td><td style="text-align:left;">SQS / Worker</td><td style="text-align:left;"><code>256 MB</code> (ARM64)</td><td style="text-align:left;"><code>10 s</code></td><td style="text-align:left;">Cola <code>flowex-consent-queue-&lt;env&gt;</code></td><td style="text-align:left;"><code>auth/jwt</code></td></tr><tr><td style="text-align:left;"><code>flowex-db-migrate-&lt;env&gt;</code> (<code>Flowex-database</code>)</td><td style="text-align:left;">Interno</td><td style="text-align:left;"><code>512 MB</code></td><td style="text-align:left;"><code>5 min</code></td><td style="text-align:left;">Invocación desde el pipeline de <code>Flowex-database</code></td><td style="text-align:left;"><code>auth/root</code> (solo prod)</td></tr></tbody></table><p>Todas leen además las credenciales de la base: <code>flowex-postgres-&lt;env&gt;-credentials</code> (usuario maestro, respaldo) y <code>flowex/&lt;env&gt;/db/app-user</code> (rol acotado). Los nombres completos llevan el prefijo <code>flowex/&lt;env&gt;/</code>. Ver la <a href="/deployment#_3-1-aws-secrets-manager-region-us-east-2">tabla de secretos</a>.</p><hr><h2 id="⚙️-variables-de-entorno" tabindex="-1">⚙️ Variables de Entorno <a class="header-anchor" href="#⚙️-variables-de-entorno" aria-label="Permalink to &quot;⚙️ Variables de Entorno&quot;">​</a></h2><p><code>Flowex-iac</code> define las variables. Ninguna contiene un valor secreto: los secretos se pasan <strong>por nombre</strong> y cada función los resuelve en Secrets Manager durante el arranque en frío.</p><h3 id="comunes-a-todas-las-funciones" tabindex="-1">Comunes a todas las funciones <a class="header-anchor" href="#comunes-a-todas-las-funciones" aria-label="Permalink to &quot;Comunes a todas las funciones&quot;">​</a></h3><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NODE_ENV=production            # development en dev</span></span>
<span class="line"><span>STAGE=prod                     # dev | prod</span></span>
<span class="line"><span>AUTH_JWT_ISSUER=flowex-auth</span></span>
<span class="line"><span>AUTH_JWT_SECRET_NAME=flowex/&lt;env&gt;/auth/jwt</span></span>
<span class="line"><span>DB_HOST=&lt;endpoint de RDS&gt;</span></span>
<span class="line"><span>DB_PORT=5432</span></span>
<span class="line"><span>DB_NAME=flowex_db</span></span>
<span class="line"><span>DB_SECRET_ARN=&lt;ARN de flowex-postgres-&lt;env&gt;-credentials&gt;</span></span>
<span class="line"><span>APP_DB_SECRET_ARN=&lt;ARN de flowex/&lt;env&gt;/db/app-user&gt;</span></span>
<span class="line"><span>DB_SSL=true</span></span>
<span class="line"><span>ERROR_SENTINEL_ENABLED=true|false</span></span>
<span class="line"><span>ERROR_SENTINEL_DISCORD_WEBHOOK_URL=&lt;desde el secret de GitHub; solo si existe&gt;</span></span>
<span class="line"><span>CONSENT_API_BASE_URL=&lt;API central de consentimiento; solo si está configurada&gt;</span></span>
<span class="line"><span>CONSENT_APP_ID=flowex</span></span>
<span class="line"><span>FRONTEND_CLOUDFRONT_URL=https://&lt;dominio de la app&gt;</span></span></code></pre></div><h3 id="por-servicio" tabindex="-1">Por servicio <a class="header-anchor" href="#por-servicio" aria-label="Permalink to &quot;Por servicio&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Función</th><th style="text-align:left;">Variables propias</th></tr></thead><tbody><tr><td style="text-align:left;"><code>auth-api</code></td><td style="text-align:left;"><code>CONSENT_QUEUE_URL</code>, <code>NOTIFICATION_QUEUE_URL</code></td></tr><tr><td style="text-align:left;"><code>auth-admin</code></td><td style="text-align:left;"><code>CONSENT_QUEUE_URL</code>, <code>NOTIFICATION_QUEUE_URL</code>, <code>NOTIFICATION_LAMBDA_NAME</code>, <code>S3_FILES_BUCKET</code>, <code>FILES_BUCKET_NAME</code>, <code>GOOGLE_MAPS_SECRET_NAME</code>, <code>ROUTE_OPTIMIZATION_SECRET_NAME</code>, <code>GCP_PROJECT_ID</code>, <code>ROUTE_PLANNING_DAILY_LIMIT</code>, <code>DELIVERY_PIN_KEY_NAME</code></td></tr><tr><td style="text-align:left;"><code>registration-public</code></td><td style="text-align:left;"><code>COMPROBANTES_BUCKET_NAME</code>, <code>FILES_BUCKET_NAME</code>, <code>NOTIFICATION_QUEUE_URL</code>, <code>CONSENT_QUEUE_URL</code></td></tr><tr><td style="text-align:left;"><code>registration-admin</code></td><td style="text-align:left;"><code>NOTIFICATION_QUEUE_URL</code>, <code>CONSENT_QUEUE_URL</code></td></tr><tr><td style="text-align:left;"><code>otp-service</code></td><td style="text-align:left;"><code>NOTIFICATION_QUEUE_URL</code>, <code>SNS_TOPIC_ARN</code>, <code>WHATSAPP_SECRET_NAME</code>, <code>CONSENT_QUEUE_URL</code>, <code>DEV_REDIRECT_WHATSAPP_PHONE</code> (solo dev)</td></tr><tr><td style="text-align:left;"><code>payments-api</code></td><td style="text-align:left;"><code>NOTIFICATION_QUEUE_URL</code>, <code>CONSENT_QUEUE_URL</code>, <code>MP_SECRET_NAME</code>, <code>FINTOC_SECRET_NAME</code>, <code>APP_URL</code>, <code>MP_NOTIFICATION_URL</code></td></tr><tr><td style="text-align:left;"><code>notification</code></td><td style="text-align:left;"><code>SES_SENDER_EMAIL</code>, <code>NOTIFICATION_QUEUE_URL</code>, <code>SNS_TOPIC_ARN</code>, <code>CONSENT_QUEUE_URL</code>, <code>DEV_REDIRECT_EMAIL</code> y <code>DEV_REDIRECT_WHATSAPP_PHONE</code> (solo dev)</td></tr><tr><td style="text-align:left;"><code>consent-worker</code></td><td style="text-align:left;"><code>CONSENT_QUEUE_URL</code></td></tr><tr><td style="text-align:left;"><code>db-migrate</code></td><td style="text-align:left;"><code>RUN_SEEDS</code> (<code>true</code> solo en dev), <code>APP_DB_SECRET_ARN</code>, <code>ROOT_ACCOUNT_SECRET_ARN</code> (solo prod)</td></tr></tbody></table><h3 id="desarrollo-local" tabindex="-1">Desarrollo local <a class="header-anchor" href="#desarrollo-local" aria-label="Permalink to &quot;Desarrollo local&quot;">​</a></h3><p>Fuera de AWS, las funciones aceptan el valor directo en lugar del nombre del secreto: <code>AUTH_JWT_SECRET</code>, <code>MP_ACCESS_TOKEN</code>, <code>MP_WEBHOOK_SECRET</code>, <code>FINTOC_SECRET_KEY</code>, <code>FINTOC_PUBLIC_KEY</code>, <code>FINTOC_WEBHOOK_SECRET</code>, <code>WHATSAPP_API_TOKEN</code>, <code>WHATSAPP_PHONE_NUMBER_ID</code>, <code>GOOGLE_MAPS_API_KEY</code>, <code>GOOGLE_ROUTE_OPTIMIZATION_KEY</code> y <code>DELIVERY_PIN_KEY</code>. Esos valores van en un <code>.env</code> local que no se versiona. La plantilla está en <code>Flowex-payments-api-lambda/.env.example</code>.</p><hr><h2 id="🛠️-compilacion-y-empaquetado" tabindex="-1">🛠️ Compilación y Empaquetado <a class="header-anchor" href="#🛠️-compilacion-y-empaquetado" aria-label="Permalink to &quot;🛠️ Compilación y Empaquetado&quot;">​</a></h2><p>Cada Lambda es un repositorio independiente con su propio <code>pnpm-lock.yaml</code>. No hay una Lambda Layer compartida: cada servicio incluye su copia de las utilidades comunes.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Flowex-auth-api-lambda</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Repetir en: auth-admin, registration-public, registration-admin, otp-service,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># payments-api, notification y consent-worker.</span></span></code></pre></div><p>El pipeline de cada repositorio empaqueta <code>dist/</code> con las dependencias de producción y ejecuta <code>aws lambda update-function-code</code>. No hace falta empaquetar a mano.</p>`,21)])])}const _=t(l,[["render",s]]);export{E as __pageData,_ as default};
